import { watchDom } from '../core/observer';
import { wasApplied, markApplied } from '../utils/dom';
import { createIcon, iconNameFromText } from '../utils/icons';

function applySidebarIcons() {
    const items = document.querySelectorAll(
        '.mainDrawer a, .mainDrawer button, .navMenuOption, .emby-button'
    );

    items.forEach((item) => {
        if (wasApplied(item, 'ptvSidebarIcon')) return;

        const label = item.getAttribute('title')
            || item.getAttribute('aria-label')
            || item.textContent
            || '';

        const iconName = iconNameFromText(label);
        if (!iconName) return;

        markApplied(item, 'ptvSidebarIcon');
        item.classList.add('ptv-sidebar-item');

        const oldIcon = item.querySelector(
            '.material-icons, .material-icons-round, .material-icons-outlined, i'
        );

        if (oldIcon) {
            oldIcon.classList.add('ptv-hidden-stock-icon');
        }

        if (!item.querySelector('.ptv-sidebar-icon')) {
            item.prepend(createIcon(iconName, 'ptv-icon ptv-sidebar-icon'));
        }
    });
}

function addPiggieHub() {
    const drawer = document.querySelector('.mainDrawer .scrollContainer, .mainDrawer');

    if (!drawer || drawer.querySelector('.ptv-hub')) return;

    const hub = document.createElement('div');
    hub.className = 'ptv-hub';

    hub.innerHTML = `
        <div class="ptv-hub-title">Piggie Hub</div>

        <a class="ptv-hub-link" href="https://request.piggietv.com" target="_blank" rel="noopener">
            <img class="ptv-icon ptv-sidebar-icon" src="/ptv-icons/request.svg" alt="">
            <span>Requests</span>
        </a>

        <a class="ptv-hub-link" href="https://music.piggietv.com" target="_blank" rel="noopener">
            <img class="ptv-icon ptv-sidebar-icon" src="/icons/music.svg" alt="">
            <span>Music</span>
        </a>

        <a class="ptv-hub-link" href="https://books.piggietv.com" target="_blank" rel="noopener">
            <img class="ptv-icon ptv-sidebar-icon" src="/icons/books.svg" alt="">
            <span>Books</span>
        </a>
    `;

    drawer.appendChild(hub);
}

function runSidebar() {
    applySidebarIcons();
    addPiggieHub();
}

watchDom(runSidebar);
runSidebar();
